SELECT t.*, , if (t.MARKET_VALUE = '02', t.MARKET_VALUE,null) prodAllAmt , if (t.MARKET_VALUE = '28', t.MARKET_VALUE,null) nowDayProfitValue , if (t.MARKET_VALUE = '29', t.MARKET_VALUE,null) nowDayRate , if (t.MARKET_VALUE = '31', t.MARKET_VALUE,null) totalRate , if (t.MARKET_VALUE = '33', t.MARKET_VALUE,null) sevenDayRate , if (t.MARKET_VALUE = '06', t.MARKET_VALUE,null) dailyAllDebt , if (t.MARKET_VALUE = '05', t.MARKET_VALUE,null) dailyAssetAllValue FROM ( SELECT DETAIL_DIST, BOOKSET_ID AS bookSetId, ( SELECT bb.ACCT_SUBJECT_ID FROM BOK_BOOKSET bb WHERE bb.BOOKSET_ID = BOK_VAL_TABLE_DATA.BOOKSET_ID) AS prodId, date_format(VAL_DATE,'%Y-%M-%D') AS valDate, IFNULL(MARKET_VALUE, cast(REGEXP_REPLACE(BOK_VAL_TABLE_DATA.SUBJECT_NAME,'[^0-9|.]','') as unsigned int)) MARKET_VALUE FROM BOK_VAL_TABLE_DATA WHERE BOOKSET_ID IN ( SELECT bookset_id FROM BOK_BOOKSET WHERE ACCT_MODE = '03') AND BOOKSET_ID in
#{item, jdbcType=VARCHAR}
AND VAL_DATE = #{exeDate, jdbcType=TIMESTAMP} AND DETAIL_DIST IN ('02','07','31','33','28','29','05','06') ) t
